def transform(grid):
 h=len(grid); w=len(grid[0]); out=[r[:] for r in grid]; seen=set(); comps=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]==0 or (r,c) in seen: continue
   seen.add((r,c)); q=[(r,c)]
   for x,y in q:
    for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]!=0:
      seen.add((a,b)); q.append((a,b))
   comps.append(q)
 for q in comps:
  rs=[x for x,y in q]; cs=[y for x,y in q]
  if min(rs)+max(rs)==h-1 and min(cs)+max(cs)==w-1:
   for x,y in q: out[x][y]=0
 return out

